"""Self-contained local UI and static result card for the operator console."""
from html import escape
import json

from .cycle_report import page
from .operator_console import contract


def render_console():
    cfg = json.dumps(contract(), ensure_ascii=False).replace('</', '<\\/')
    return '''<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; img-src 'self' data:">
<title>Нефтекод · операторская консоль</title><style>
:root{--bg:#07110f;--panel:#10201c;--line:#29433b;--ink:#eef8f4;--muted:#a3bbb2;--lime:#b8f25b;--amber:#ffc76b;--red:#ff918d;--blue:#72c9f4}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,#17372e 0,transparent 35%),var(--bg);color:var(--ink);font:15px/1.5 ui-sans-serif,system-ui,-apple-system,sans-serif}main{max-width:1260px;margin:auto;padding:32px 20px 72px}.eyebrow{color:var(--lime);font-size:12px;letter-spacing:.14em;text-transform:uppercase}h1{font-size:clamp(32px,5vw,60px);line-height:1.02;margin:.25em 0}h2{margin:0 0 16px;font-size:23px}h3{font-size:16px;margin:0 0 12px}.lead{max-width:850px;color:var(--muted);font-size:17px}.banner{border:1px solid #61522d;background:#241e0f;color:#ffe0a6;border-radius:12px;padding:12px 15px;margin:22px 0}.layout{display:grid;grid-template-columns:1fr 1.15fr;gap:18px}.layout>*,.panel,.group{min-width:0}.panel{background:color-mix(in srgb,var(--panel) 94%,transparent);border:1px solid var(--line);border-radius:18px;padding:20px;margin-top:18px;box-shadow:0 18px 50px #0004}.row{display:flex;gap:12px;align-items:end;flex-wrap:wrap}.grow{flex:1;min-width:230px}label{display:block;color:var(--muted);font-size:12px;margin:0 0 6px}input,select,button{font:inherit}input,select{width:100%;border:1px solid var(--line);border-radius:9px;background:#0a1714;color:var(--ink);padding:10px}input:focus,button:focus{outline:2px solid var(--blue);outline-offset:2px}.check{display:flex;align-items:center;gap:8px;color:var(--ink);font-size:14px;margin:10px 0}.check input{width:auto}button{border:0;border-radius:9px;background:var(--lime);color:#11200d;font-weight:750;padding:11px 15px;cursor:pointer}button.secondary{background:#203c34;color:var(--ink);border:1px solid var(--line)}button:disabled{opacity:.45;cursor:wait}.pills{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.pill{padding:5px 8px;border-radius:999px;background:#173229;color:var(--muted);font-size:12px}.ok{color:var(--lime)}.warn{color:var(--amber)}.bad{color:var(--red)}.groups{display:grid;grid-template-columns:1fr 1fr;gap:12px}.group{border:1px solid var(--line);border-radius:12px;padding:12px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field small{display:block;color:#718d83}.status{border-left:4px solid var(--amber);background:#18241f;border-radius:8px;padding:12px;margin:14px 0}.status.plan{border-color:var(--lime)}.status.error{border-color:var(--red)}.table{max-width:100%;overflow:auto;border:1px solid var(--line);border-radius:10px;margin-top:10px}table{border-collapse:collapse;width:100%;min-width:620px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid #20372f;font-size:12px;vertical-align:top}th{color:var(--muted);position:sticky;top:0;background:#11221d}code{color:#c8f4e4;overflow-wrap:anywhere}.empty{color:var(--muted);padding:16px;border:1px dashed var(--line);border-radius:10px}.foot{color:var(--muted);margin-top:18px;font-size:12px;overflow-wrap:anywhere}@media(max-width:900px){.layout,.groups{grid-template-columns:minmax(0,1fr)}main{padding:22px 12px}.panel{padding:15px}.fields{grid-template-columns:1fr 1fr}}@media(max-width:480px){.fields{grid-template-columns:1fr}button{width:100%}}
</style></head><body><main><div class="eyebrow">Нефтекод / локальный контур</div><h1>История отдельно.<br>Модельные допущения явно.</h1><p class="lead">Загрузите архивный срез, проверьте доступность лабораторных событий, затем задайте полный модельный сценарий. Только входной T95 может прийти из ЛИМС — через отдельно включённую консервативную границу sample + 4 ч.</p><div class="banner"><strong>Это модельный расчёт.</strong> Историческая телеметрия не считается онлайн-признаком, ПАК исключён, а результат не является восстановленной исторической или промышленной командой.</div>
<div class="layout"><section><div class="panel"><h2>1 · Исторический срез</h2><div class="row"><div class="grow"><label for="asof">Локальное время источников</label><input id="asof" type="datetime-local" step="60" list="origins"></div><button id="load">Загрузить срез</button></div><datalist id="origins"></datalist><label class="check"><input id="upper" type="checkbox">Явно применить верхнюю границу публикации ЛИМС sample + 4 ч</label><div id="history"><div class="empty">Срез ещё не загружен.</div></div></div></section>
<section><div class="panel"><h2>2 · Модельный сценарий</h2><div class="row"><button class="secondary" id="demo">Загрузить демонстрационные допущения</button><button id="calculate">Рассчитать сценарий</button></div><label class="check"><input id="bind" type="checkbox">Взять T95 входа ГТ из допустимой пробы ЛИМС текущего среза</label><p class="foot">Кнопка допущений заполняет учебный пример. Эти числа не извлечены из архива. При расчёте также явно фиксируется data_ok=true.</p><div id="groups" class="groups"></div><div id="result"><div class="empty">Результат появится после явного расчёта.</div></div></div></section></div>
<p class="foot">Сервис работает на loopback. Пути к данным и SHA задаются при запуске Python; браузер их не меняет. Каждый вызов сохраняет локальный аудит.</p></main>
<script>const C=''' + cfg + ''';const $=id=>document.getElementById(id);let loaded=null;
const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso=()=>{const v=$('asof').value;if(!v)throw Error('Укажите время среза');return v.length===16?v+':00':v};
C.demo_origins.forEach(v=>{const o=document.createElement('option');o.value=v.slice(0,16);$('origins').append(o)});$('asof').value=C.demo_origins[0].slice(0,16);
for(const g of C.field_groups){const box=document.createElement('div');box.className='group';box.innerHTML='<h3>'+esc(g.title)+'</h3><div class="fields"></div>';for(const name of g.fields){const [label,unit]=C.labels[name];const d=document.createElement('div');d.className='field';d.innerHTML='<label for="f-'+name+'">'+esc(label)+'</label><input id="f-'+name+'" inputmode="decimal" placeholder="явное значение"><small>'+esc(unit)+'</small>';box.querySelector('.fields').append(d)}$('groups').append(box)}
function setBusy(v){$('load').disabled=v;$('calculate').disabled=v}
async function post(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok||j.status==='TOOL_ERROR')throw Error((j.reasons||['HTTP '+r.status]).join('; '));return j}
function historyView(s){const selected=s.lims_series_status.map(r=>'<tr><td>'+esc(r.field)+'</td><td>'+esc(r.value)+'</td><td>'+esc(r.unit)+'</td><td>'+esc(r.event_time)+'</td><td>'+esc(r.status)+'</td><td>'+esc((r.reasons||[]).join(', '))+'</td></tr>').join('');const controls=s.telemetry.channels.filter(r=>r.context).map(r=>'<tr><td>'+esc(r.tag)+'</td><td>'+esc(r.context.description)+'</td><td>'+esc(r.archive_value)+'</td><td>'+esc(r.event_time)+'</td><td>'+esc((r.flags||[]).join(', ')||'—')+'</td></tr>').join('');$('history').innerHTML='<div class="status"><strong>'+esc(s.decision.status)+'</strong><div>Архив прочитан; рекомендация отсутствует.</div></div><div class="pills"><span class="pill">ЛИМС '+Object.keys(s.selected_lims).length+'/5</span><span class="pill">HT '+s.telemetry.channels.length+' каналов</span><span class="pill">ПАК исключён</span></div><h3>Лабораторные серии</h3><div class="table"><table><thead><tr><th>Поле</th><th>Значение</th><th>Ед.</th><th>Проба</th><th>Статус</th><th>Причина</th></tr></thead><tbody>'+selected+'</tbody></table></div><h3 style="margin-top:16px">P8 / T11 / F19 · только контекст</h3><div class="table"><table><thead><tr><th>Тег</th><th>Роль</th><th>Архив</th><th>Время</th><th>Замечания</th></tr></thead><tbody>'+controls+'</tbody></table></div><p class="foot">Аудит: <code>'+esc(s.audit_manifest)+'</code></p>'}
function readScenario(){const state={};for(const name of C.scenario_schema.required){if(name==='data_ok'){state[name]=true;continue}if(name==='feed_t95'&&$('bind').checked)continue;const input=$('f-'+name);if(!input||input.value.trim()==='')throw Error('Заполните поле '+name);const v=Number(input.value.replace(',','.'));if(!Number.isFinite(v))throw Error('Некорректное число '+name);state[name]=v}return state}
function resultView(s){const d=s.decision,plan=s.recommendation;let detail='<p>Плана исходного заказа нет.</p>';if(plan){detail='<div class="pills"><span class="pill">T '+esc(plan.command.temperature)+' °C</span><span class="pill">P '+esc(plan.command.pressure)+' MPa</span><span class="pill">Q '+esc(plan.command.feed)+' т/ч</span><span class="pill">Выпуск '+esc(plan.delivered_mass)+' т</span></div><p>Верхняя модельная оценка удельных затрат: <strong>'+esc(plan.unit_cost_upper)+'</strong>.</p>'}const prov=Object.entries(s.input_provenance).map(([k,v])=>'<tr><td>'+esc(k)+'</td><td>'+esc(v.basis)+'</td><td>'+esc(v.event_time||v.origin)+'</td></tr>').join('');$('result').innerHTML='<div class="status '+(plan?'plan':'')+'"><strong>'+esc(d.status)+'</strong><div>'+esc(d.explanation||(d.reasons||[]).join(', '))+'</div>'+detail+'</div><h3>Происхождение входов</h3><div class="table"><table><thead><tr><th>Поле</th><th>Основание</th><th>Время</th></tr></thead><tbody>'+prov+'</tbody></table></div><p class="foot">historical_recommendation=false · industrial_command=false<br>Аудит: <code>'+esc(s.audit_manifest)+'</code></p>'}
$('demo').onclick=()=>{for(const [k,v] of Object.entries(C.demo_state)){const e=$('f-'+k);if(e)e.value=v}};
$('bind').onchange=()=>{const e=$('f-feed_t95');e.disabled=$('bind').checked;e.placeholder=$('bind').checked?'из допустимой ЛИМС':'явное значение'};
$('load').onclick=async()=>{setBusy(true);try{loaded=await post('/api/history',{as_of:iso(),use_lims_upper_bound:$('upper').checked});historyView(loaded)}catch(e){$('history').innerHTML='<div class="status error"><strong>Ошибка</strong><div>'+esc(e.message)+'</div></div>'}finally{setBusy(false)}};
$('calculate').onclick=async()=>{setBusy(true);try{if(!loaded||loaded.as_of!==iso()||loaded.use_lims_upper_bound!==$('upper').checked)throw Error('Сначала загрузите срез с текущими временем и правилом ЛИМС');const out=await post('/api/evaluate',{as_of:iso(),use_lims_upper_bound:$('upper').checked,use_historical_feed_t95:$('bind').checked,scenario:readScenario()});resultView(out)}catch(e){$('result').innerHTML='<div class="status error"><strong>Ошибка</strong><div>'+esc(e.message)+'</div></div>'}finally{setBusy(false)}};
</script></body></html>'''


def render_result(package):
    e = lambda value: escape('—' if value is None else str(value))
    decision = package['decision']; plan = package['recommendation']
    plan_html = '<p>Допустимого полного плана исходного заказа нет.</p>'
    if plan:
        command = plan['command']
        plan_html = (f"<p><strong>T {e(command['temperature'])} °C · P {e(command['pressure'])} MPa · "
                     f"Q {e(command['feed'])} т/ч</strong></p><p>Выпуск {e(plan['delivered_mass'])} т; "
                     f"верхняя модельная оценка удельных затрат {e(plan['unit_cost_upper'])}.</p>")
    rows = ''.join('<tr><td>' + e(name) + '</td><td>' + e(info['basis']) + '</td><td>' +
                   e(info.get('event_time') or info.get('origin')) + '</td></tr>'
                   for name, info in package['input_provenance'].items())
    body = f'''<div class="eyebrow">Нефтекод / модельный сценарий на срезе</div>
<h1>{e(decision['status'])}</h1><div class="status"><strong>Не историческая рекомендация</strong>
<p>{e(decision.get('explanation') or ', '.join(decision.get('reasons', [])))}</p>{plan_html}</div>
<h2>Происхождение входов</h2><div class="table"><table><thead><tr><th>Поле</th><th>Основание</th><th>Время</th></tr></thead><tbody>{rows}</tbody></table></div>
<footer>historical_recommendation=false · industrial_command=false · model_effect_validated_on_history=false</footer>'''
    return page('Модельный сценарий · ' + package['as_of'], body)
